-- AllInFashion kliens cím-törzsadatok, INS SIRUTA S1 2025 alapján
-- Idempotens: biztonságosan újrafuttatható.
BEGIN;
CREATE TABLE IF NOT EXISTS aif_ro_counties (code text PRIMARY KEY, name text NOT NULL, siruta_code text NULL, siruta_jud integer NULL, priority integer NOT NULL DEFAULT 100, source_version text NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS aif_ro_counties_siruta_jud_uq ON aif_ro_counties (siruta_jud) WHERE siruta_jud IS NOT NULL;
CREATE INDEX IF NOT EXISTS aif_ro_counties_active_sort_idx ON aif_ro_counties (is_active, priority, name);
CREATE TABLE IF NOT EXISTS aif_ro_localities (siruta_code text PRIMARY KEY, name text NOT NULL, official_name text NULL, county_code text NOT NULL REFERENCES aif_ro_counties(code), parent_siruta_code text NULL, postal_code text NULL, locality_type integer NULL, admin_level integer NULL, urban_rural integer NULL, source_version text NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS aif_ro_localities_county_name_idx ON aif_ro_localities (county_code, lower(name)) WHERE is_active=true;
CREATE INDEX IF NOT EXISTS aif_ro_localities_postal_idx ON aif_ro_localities (postal_code) WHERE postal_code IS NOT NULL;
ALTER TABLE IF EXISTS aif_shop_customers ADD COLUMN IF NOT EXISTS country_code text NOT NULL DEFAULT 'RO';
ALTER TABLE IF EXISTS aif_shop_customers ADD COLUMN IF NOT EXISTS county_code text DEFAULT NULL;
ALTER TABLE IF EXISTS aif_shop_customers ADD COLUMN IF NOT EXISTS county_name text DEFAULT NULL;
ALTER TABLE IF EXISTS aif_shop_customers ADD COLUMN IF NOT EXISTS locality_code text DEFAULT NULL;
ALTER TABLE IF EXISTS aif_shop_customers ADD COLUMN IF NOT EXISTS locality_name text DEFAULT NULL;
ALTER TABLE IF EXISTS aif_shop_customers ADD COLUMN IF NOT EXISTS postal_code text DEFAULT NULL;
CREATE INDEX IF NOT EXISTS aif_shop_customers_county_idx ON aif_shop_customers (county_code) WHERE county_code IS NOT NULL;
CREATE INDEX IF NOT EXISTS aif_shop_customers_locality_idx ON aif_shop_customers (locality_code) WHERE locality_code IS NOT NULL;
UPDATE aif_ro_counties SET is_active=false WHERE COALESCE(source_version,'') <> 'SIRUTA_S1_2025';
UPDATE aif_ro_localities SET is_active=false WHERE COALESCE(source_version,'') <> 'SIRUTA_S1_2025';
ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name,siruta_code=EXCLUDED.siruta_code,siruta_jud=EXCLUDED.siruta_jud,priority=EXCLUDED.priority,source_version=EXCLUDED.source_version,is_active=true,updated_at=now();
ON CONFLICT (siruta_code) DO UPDATE SET name=EXCLUDED.name,official_name=EXCLUDED.official_name,county_code=EXCLUDED.county_code,parent_siruta_code=EXCLUDED.parent_siruta_code,postal_code=EXCLUDED.postal_code,locality_type=EXCLUDED.locality_type,admin_level=EXCLUDED.admin_level,urban_rural=EXCLUDED.urban_rural,source_version=EXCLUDED.source_version,is_active=true,updated_at=now();
